function prepareProject(payload, workspaceId) {
  const fields = payload?.attributes;
  const identifier = (value) =>
    (typeof value === "string" && value.trim().length > 0) || Number.isSafeInteger(value);
  if (
    !fields ||
    !identifier(fields.number) ||
    !identifier(fields.id) ||
    typeof fields.customer_business_then_name !== "string" ||
    !fields.customer_business_then_name.trim()
  ) {
    return {
      ready: false,
      status: 400,
      response: { error: "Supply the Syncro ticket number, customer name and ID." },
    };
  }
  if (
    typeof workspaceId !== "string" ||
    !/^[A-Za-z0-9_-]+$/.test(workspaceId) ||
    workspaceId === "YOUR_CLOCKIFY_WORKSPACE_ID"
  ) {
    return {
      ready: false,
      status: 503,
      response: { error: "Select a Clockify workspace before enabling this webhook." },
    };
  }
  const name =
    "Ticket " + fields.number + " - " + fields.customer_business_then_name + " [" + fields.id + "]";
  return {
    ready: true,
    endpoint: "/workspaces/" + workspaceId + "/projects",
    request: { name },
    name,
    workspaceId,
  };
}
const workspaceId = "YOUR_CLOCKIFY_WORKSPACE_ID";
return [{ json: prepareProject($input.first().json.body, workspaceId) }];

function projectReceipt(status, response, expected) {
  if (
    status !== 201 ||
    !response ||
    typeof response !== "object" ||
    Array.isArray(response) ||
    typeof response.id !== "string" ||
    !response.id.trim() ||
    response.name !== expected.name ||
    response.workspaceId !== expected.workspaceId
  ) {
    return {
      status: 502,
      body: {
        error:
          "Clockify did not confirm the project. Check the workspace before sending this ticket again.",
      },
    };
  }
  return { status: 200, body: [response] };
}
const { statusCode, body } = $input.first().json;
return [
  {
    json: projectReceipt(statusCode, body, $("Set workspace and read ticket fields").first().json),
  },
];
